import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        m = int(next(iterator))
        s = int(next(iterator))
    except StopIteration:
        return

    adj = [[] for _ in range(n + 1)]
    for _ in range(m):
        u = int(next(iterator))
        v = int(next(iterator))
        adj[u].append(v)

    # Step 1: Find all nodes reachable from s using BFS/DFS
    visited_from_s = [False] * (n + 1)
    queue = deque([s])
    visited_from_s[s] = True
    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if not visited_from_s[v]:
                visited_from_s[v] = True
                queue.append(v)

    # Count unreachable nodes
    unreachable_count = sum(1 for i in range(1, n + 1) if not visited_from_s[i])
    if unreachable_count == 0:
        print(0)
        return

    # Step 2: Build condensation graph (SCCs)
    # We only care about SCCs formed by unreachable nodes and their connections.
    # Actually, we need to find SCCs for the whole graph, but focus on those not reachable from s.

    # Tarjan's algorithm or Kosaraju's to find SCCs
    # Using Kosaraju's for clarity

    # First pass: DFS on original graph to get finish order
    visited_all = [False] * (n + 1)
    order = []

    def dfs1(u):
        stack = [(u, False)]
        while stack:
            node, processed = stack.pop()
            if processed:
                order.append(node)
                continue
            if visited_all[node]:
                continue
            visited_all[node] = True
            stack.append((node, True))
            for v in adj[node]:
                if not visited_all[v]:
                    stack.append((v, False))

    for i in range(1, n + 1):
        if not visited_all[i]:
            dfs1(i)

    # Build reverse graph
    rev_adj = [[] for _ in range(n + 1)]
    for u in range(1, n + 1):
        for v in adj[u]:
            rev_adj[v].append(u)

    # Second pass: DFS on reverse graph in reverse finish order
    visited_scc = [False] * (n + 1)
    scc_id = [-1] * (n + 1)
    scc_count = 0

    def dfs2(u, cid):
        stack = [u]
        visited_scc[u] = True
        scc_id[u] = cid
        while stack:
            node = stack.pop()
            for v in rev_adj[node]:
                if not visited_scc[v]:
                    visited_scc[v] = True
                    scc_id[v] = cid
                    stack.append(v)

    for i in range(len(order) - 1, -1, -1):
        node = order[i]
        if not visited_scc[node]:
            dfs2(node, scc_count)
            scc_count += 1

    # Step 3: Calculate in-degree of each SCC in the condensation graph
    # Only consider edges between different SCCs
    scc_in_degree = [0] * scc_count

    for u in range(1, n + 1):
        u_scc = scc_id[u]
        for v in adj[u]:
            v_scc = scc_id[v]
            if u_scc != v_scc:
                scc_in_degree[v_scc] += 1

    # Step 4: Count SCCs with in-degree 0 that do NOT contain s
    # These are the "source" components in the condensation graph that are not reachable from s.
    # Each such component needs at least one incoming edge from somewhere reachable (or from another newly connected component).
    # The minimum number of edges needed is exactly the count of such source SCCs.

    s_scc = scc_id[s]
    ans = 0
    for i in range(scc_count):
        if i == s_scc:
            continue
        if scc_in_degree[i] == 0:
            ans += 1

    print(ans)

if __name__ == '__main__':
    solve()
